sealed interface AuthError {
    data object WrongCredentials : AuthError
    data object EmailInUse : AuthError
    data object WeakPassword : AuthError
    data object Offline : AuthError
    data class Unknown(val e: Throwable) : AuthError
}

suspend fun FirebaseAuth.signUp(email: String, password: String): Result<FirebaseUser> = try {
    Result.success(createUserWithEmailAndPassword(email, password).await().user!!)
} catch (e: Exception) {
    Result.failure(AuthException(when (e) {
        is FirebaseAuthWeakPasswordException -> AuthError.WeakPassword
        is FirebaseAuthUserCollisionException -> AuthError.EmailInUse
        is FirebaseAuthInvalidCredentialsException -> AuthError.WrongCredentials
        is FirebaseNetworkException -> AuthError.Offline
        else -> AuthError.Unknown(e)
    }))
}

class RootViewModel(auth: AuthRepository) : ViewModel() {
    val destination: StateFlow<Root> = auth.currentUser
        .map { if (it == null) Root.SignIn else Root.Home }
        .stateIn(viewModelScope, SharingStarted.Eagerly, Root.Loading)
}

suspend fun AuthRepository.upgradeToGoogle(activity: Activity, webClientId: String): UpgradeResult {
    val anonymous = auth.currentUser ?: return UpgradeResult.NotSignedIn
    val google = googleCredential(activity, webClientId)
    return try {
        anonymous.linkWithCredential(google).await()
        UpgradeResult.Linked                                // same uid, data kept
    } catch (e: FirebaseAuthUserCollisionException) {
        val localData = exportLocalData()
        auth.signInWithCredential(google).await()           // the existing account
        UpgradeResult.ExistingAccount(localData)            // let the user choose to merge
    }
}

class AuthHeaderInterceptor(private val auth: FirebaseAuth) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        val token = runBlocking { auth.currentUser?.getIdToken(false)?.await()?.token }
        val request = chain.request().newBuilder()
            .apply { token?.let { header("Authorization", "Bearer $it") } }
            .build()
        return chain.proceed(request)
    }
}

data class Post(
    @DocumentId val id: String = "",
    val authorId: String = "",
    val authorName: String = "",          // denormalised: no extra read per post
    val text: String = "",
    val likeCount: Long = 0,
    @ServerTimestamp val createdAt: Timestamp? = null,
)

class FeedRepository(private val db: FirebaseFirestore) {
    fun latest(limit: Long = 30): Flow<List<Post>> =
        db.collection("posts")
            .orderBy("createdAt", Query.Direction.DESCENDING)
            .limit(limit)
            .snapshots(MetadataChanges.INCLUDE)
            .map { it.toObjects<Post>() }

    fun byAuthor(uid: String): Flow<List<Post>> =
        db.collection("posts").whereEqualTo("authorId", uid)
            .orderBy("createdAt", Query.Direction.DESCENDING)   // needs a composite index
            .snapshots().map { it.toObjects<Post>() }
}

class FeedViewModel(repo: FeedRepository) : ViewModel() {
    val posts = repo.latest().stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), emptyList())
}

