service cloud.firestore {
  match /databases/{database}/documents {
    match /{document=**} { allow read, write: if false; }          // deny by default

    match /users/{uid}/notes/{noteId} {
      allow read, delete: if request.auth != null && request.auth.uid == uid;
      allow create, update: if request.auth != null && request.auth.uid == uid
        && request.resource.data.keys().hasOnly(['title', 'body', 'updatedAt'])
        && request.resource.data.title is string
        && request.resource.data.title.size() <= 200
        && request.resource.data.body.size() <= 20000;
    }

    match /posts/{postId} {
      allow read: if request.auth != null;
      allow create: if request.auth != null && request.resource.data.authorId == request.auth.uid;
      allow update: if request.auth != null
        && request.resource.data.diff(resource.data).affectedKeys().hasOnly(['likeCount']);
    }
  }
}

class TokenSyncWorker(ctx: Context, p: WorkerParameters, private val api: DeviceApi, private val auth: FirebaseAuth) :
    CoroutineWorker(ctx, p) {
    override suspend fun doWork(): Result {
        val uid = auth.currentUser?.uid ?: return Result.success()     // nothing to link yet
        val token = inputData.getString("token") ?: FirebaseMessaging.getInstance().token.await()
        return try {
            api.upsertDevice(DeviceDto(uid = uid, token = token, platform = "android"))
            Result.success()
        } catch (e: IOException) { Result.retry() }
    }
    companion object {
        fun enqueue(context: Context, token: String? = null) = WorkManager.getInstance(context).enqueueUniqueWork(
            "token-sync", ExistingWorkPolicy.REPLACE,
            OneTimeWorkRequestBuilder<TokenSyncWorker>()
                .setInputData(workDataOf("token" to token))
                .setConstraints(Constraints(requiredNetworkType = NetworkType.CONNECTED))
                .build())
    }
}

// Cloud Function (TypeScript): notify a seller on all devices and clean dead tokens
import { getMessaging } from "firebase-admin/messaging";
import { getFirestore } from "firebase-admin/firestore";

export async function notifyItemSold(sellerId: string, itemId: string) {
  const devices = await getFirestore().collection(`users/${sellerId}/devices`).get();
  const tokens = devices.docs.map((d) => d.get("token") as string);
  if (tokens.length === 0) return;

  const res = await getMessaging().sendEachForMulticast({
    tokens,
    data: { type: "item_sold", itemId },
    android: { priority: "high", ttl: 3600 * 1000, collapseKey: `sold-${itemId}` },
  });

  await Promise.all(res.responses.map((r, i) => {
    const code = r.error?.code;
    const dead = code === "messaging/registration-token-not-registered" || code === "messaging/invalid-argument";
    return dead ? devices.docs[i].ref.delete() : Promise.resolve();
  }));
}

class FlagsInitializer(private val flags: RemoteFeatureFlags, private val scope: CoroutineScope) {
    suspend fun onAppStart() {
        flags.activateAtStartup()                  // values fetched last time: no UI jump now
        scope.launch {
            runCatching { flags.fetchForNextLaunch() }   // background, for the next start
        }
    }
}

