class PhotoUploadWorker(ctx: Context, p: WorkerParameters, private val storage: FirebaseStorage,
                        private val db: FirebaseFirestore, private val auth: FirebaseAuth) : CoroutineWorker(ctx, p) {
    override suspend fun doWork(): Result {
        val uid = auth.currentUser?.uid ?: return Result.failure()
        val postId = inputData.getString("postId")!!
        val file = File(inputData.getString("path")!!)
        val jpeg = compressToJpeg(file, maxSide = 1600, quality = 80)          // ~300 KB instead of 12 MB
        val ref = storage.reference.child("users/$uid/posts/$postId.jpg")
        return try {
            ref.putBytes(jpeg, storageMetadata { contentType = "image/jpeg" })
                .addOnProgressListener { s ->
                    setProgressAsync(workDataOf("p" to (100 * s.bytesTransferred / s.totalByteCount).toInt()))
                }.await()
            db.document("posts/$postId").update("imagePath", ref.path).await()
            Result.success()
        } catch (e: StorageException) {
            if (e.isRecoverableException) Result.retry() else Result.failure()
        }
    }
}

