import { onCall, HttpsError } from "firebase-functions/v2/https";
import { onDocumentCreated } from "firebase-functions/v2/firestore";
import { getFirestore, FieldValue } from "firebase-admin/firestore";

export const submitQuiz = onCall({ enforceAppCheck: true }, async (req) => {
  if (!req.auth) throw new HttpsError("unauthenticated", "Sign in first");
  const { quizId, answers } = req.data as { quizId: string; answers: number[] };
  const quiz = await getFirestore().doc(`quizzes/${quizId}`).get();
  if (!quiz.exists) throw new HttpsError("not-found", "Unknown quiz");
  const correct: number[] = quiz.get("answers");               // never sent to the client
  const score = answers.filter((a, i) => a === correct[i]).length;
  await getFirestore().doc(`users/${req.auth.uid}/scores/${quizId}`).set({ score }, { merge: true });
  return { score, total: correct.length };
});

export const countPosts = onDocumentCreated("posts/{postId}", async (event) => {
  const authorId = event.data?.get("authorId");
  const marker = getFirestore().doc(`processedEvents/${event.id}`);   // idempotency
  await getFirestore().runTransaction(async (tx) => {
    if ((await tx.get(marker)).exists) return;
    tx.set(marker, { at: FieldValue.serverTimestamp() });
    tx.update(getFirestore().doc(`users/${authorId}`), { postCount: FieldValue.increment(1) });
  });
});
